import { z } from "zod";

export const RunScope = z.object({
  runId: z.string(),
  repo: z.string(),
  branch: z.string(),
  slackThreadTs: z.string().nullable(),
});
export type RunScope = z.infer<typeof RunScope>;

{
  "name": "@rhinohealth/ai-agents",
  "private": true,
  "type": "module",
  "workspaces": ["shared", "broker", "orchestrator"],
  "scripts": {
    "typecheck": "npm run typecheck --workspaces --if-present",
    "pretest": "npm run build --workspace shared",
    "test": "node --import tsx --test --test-reporter=spec \"*/test/**/*.test.ts\""
  }
}

follow.do:
for pkg in broker orchestrator; do
cat > $pkg/package.json <<EOF
{ "name": "@rhinohealth/ai-agents-$pkg", "version": "0.1.0", "type": "module",
  "dependencies": { "@rhinohealth/ai-agents-shared": "0.1.0" },
  "scripts": { "build": "tsc -p tsconfig.json", "typecheck": "tsc -p tsconfig.json --noEmit" } }
EOF
done
cat > broker/src/scopes.ts <<'EOF'
import { RunScope } from "@rhinohealth/ai-agents-shared";

export const openScope = (body: unknown): RunScope => RunScope.parse(body);
export const canPost = (scope: RunScope): boolean => scope.slackThreadTs !== null;
EOF
cat > orchestrator/src/open-run.ts <<'EOF'
import type { RunScope } from "@rhinohealth/ai-agents-shared";

export const scopeFor = (ticket: string, threadTs: string): RunScope => ({
  runId: `run-${ticket}`,
  repo: "RhinoHealth/fcp",
  branch: `nova/${ticket}`,
  slackThreadTs: threadTs,
});
EOF
cat > broker/test/scopes.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { canPost, openScope } from "../src/scopes.js";

test("a run with a Slack thread may post in it", () => {
  const scope = openScope({ runId: "run-1", repo: "RhinoHealth/fcp", branch: "nova/RH-1234", slackThreadTs: "1760.42" });
  assert.equal(canPost(scope), true);
});
EOF
cat > orchestrator/test/open-run.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { RunScope } from "@rhinohealth/ai-agents-shared";
import { scopeFor } from "../src/open-run.js";

test("the scope the orchestrator sends is one the broker accepts", () => {
  assert.doesNotThrow(() => RunScope.parse(scopeFor("RH-1234", "1760.42")));
});
EOF

